INSERT INTO reviews (attraction_name, district, review_text, sentiment, aspect) VALUES
('องค์พระปฐมเจดีย์', 'เมืองนครปฐม', 'สถานที่สวยงามมาก บรรยากาศร่มรื่น เหมาะแก่การมาพักผ่อนและทำบุญกับครอบครัว', 'positive', 'บรรยากาศและความสวยงาม'),
('องค์พระปฐมเจดีย์', 'เมืองนครปฐม', 'ไปทำบุญที่องค์พระปฐมเจดีย์มา ประทับใจมาก องค์พระสวยงาม อลังการ สะอาดสะอ้าน มีจุดไหว้พระขอพรหลายจุด', 'positive', 'บรรยากาศและความสวยงาม'),
('องค์พระปฐมเจดีย์', 'เมืองนครปฐม', 'ของกินอร่อยเยอะมากรอบองค์พระ ราคาไม่แพง พ่อค้าแม่ค้าใจดี อัธยาศัยดีมาก แนะนำเลยครับ', 'positive', 'อาหารและของกิน'),
('องค์พระปฐมเจดีย์', 'เมืองนครปฐม', 'สถานที่สวยงามและศักดิ์สิทธิ์มาก แต่คนเยอะมากในวันหยุด หาที่จอดรถค่อนข้างยาก', 'neutral', 'ที่จอดรถและการเดินทาง'),
('วัดไร่ขิงพระอารามหลวง', 'สามพราน', 'ไปทำบุญที่วัดไร่ขิงมา หลวงพ่อศักดิ์สิทธิ์มาก บรรยากาศริมแม่น้ำร่มรื่น สบายใจมาก', 'positive', 'บรรยากาศและความสวยงาม'),
('วัดไร่ขิงพระอารามหลวง', 'สามพราน', 'การจัดการดี ที่จอดรถกว้างขวาง มีเจ้าหน้าที่คอยโบกรถและให้คำแนะนำอย่างดี', 'positive', 'ที่จอดรถและการเดินทาง'),
('วัดไร่ขิงพระอารามหลวง', 'สามพราน', 'ทางเข้าวัดรถติดมาก การจราจรติดขัดช่วงเทศกาล ควรเผื่อเวลาเดินทาง', 'negative', 'ที่จอดรถและการเดินทาง'),
('ตลาดน้ำดอนหวาย', 'สามพราน', 'แวะมาเดินเล่นที่ตลาดน้ำดอนหวาย ของกินอร่อยเยอะมาก เป็ดพะโล้ ขนมไทยโบราณรสชาติดีมาก', 'positive', 'อาหารและของกิน'),
('ตลาดน้ำดอนหวาย', 'สามพราน', 'ของฝากหลากหลาย ขนมตาล ขนมเปี๊ยะอร่อย เดินเพลินๆ ชิลๆ แนะนำให้มาครับ', 'positive', 'อาหารและของกิน'),
('ตลาดน้ำดอนหวาย', 'สามพราน', 'ที่จอดรถไม่เพียงพอ ต้องวนหาอยู่นาน และทางเดินอากาศค่อนข้างร้อนอบอ้าว', 'negative', 'ที่จอดรถและการเดินทาง'),
('Bubble in the forest', 'สามพราน', 'คาเฟ่สวยสไตล์มัลดีฟส์ มุมถ่ายรูปเยอะมาก อาหารและเครื่องดื่มจัดจานสวย', 'positive', 'บรรยากาศและความสวยงาม'),
('Bubble in the forest', 'สามพราน', 'สถานที่สวยงามตกแต่งอลังการ แต่คนต่อคิวถ่ายรูปเยอะมาก ต้องรอจังหวะนาน', 'neutral', 'การบริการและความแออัด'),
('Bubble in the forest', 'สามพราน', 'ราคาอาหารและเครื่องดื่มค่อนข้างแพง และเวลารอคิวโต๊ะนานเกินไปในวันหยุด', 'negative', 'ราคาและความคุ้มค่า'),
('Dubua Café', 'นครชัยศรี', 'สถานที่กว้างมาก มีสัตว์ให้เด็กๆ ให้อาหาร บรรยากาศในสวนบัวร่มรื่น เหมาะกับครอบครัว', 'positive', 'บรรยากาศและความสวยงาม'),
('Dubua Café', 'นครชัยศรี', 'ร้านกาแฟในฟาร์ม มีจักรยานน้ำให้ปั่นฟรี มีของกินให้เลือกหลายโซน คุ้มค่าที่ได้มา', 'positive', 'ราคาและความคุ้มค่า'),
('เจษฎาเทคนิค มิวเซียม', 'นครชัยศรี', 'รถโบราณและยานยนต์หายากเยอะมาก ตื่นตาตื่นใจ ได้ความรู้ เข้าชมฟรีไม่มีค่าใช้จ่าย', 'positive', 'ราคาและความคุ้มค่า'),
('วัดประชาราษฎร์บำรุง (วัดรางหมัน)', 'กำแพงแสน', 'วิหารสวยงามอลังการสีทองอร่าม บารมีหลวงปู่แผ้ว ไหว้พระแล้วรู้สึกสบายใจ วัดสะอาดมาก', 'positive', 'บรรยากาศและความสวยงาม'),
('วัดดอนขนาก', 'เมืองนครปฐม', 'ลอดถ้ำพญานาคสวยงามตระการตา จุดเช็คอินสายมูไม่ควรพลาด แต่เสาร์อาทิตย์คนเยอะมาก', 'neutral', 'การบริการและความแออัด'),
('ตลาดน้ำลำพญา', 'บางเลน', 'ตลาดน้ำบรรยากาศบ้านๆ ริมแม่น้ำท่าจีน ผักสดผลไม้จากชาวสวนราคาถูกมาก นั่งแพชิลๆ', 'positive', 'อาหารและของกิน'),
('ตลาดน้ำทุ่งบัวแดง', 'บางเลน', 'ทุ่งบัวแดงสวยงามตระการตา นั่งเรือพายถ่ายรูปสวยมาก มีโดรนถ่ายมุมสูงให้ด้วย', 'positive', 'บรรยากาศและความสวยงาม'),
('พระราชวังสนามจันทร์', 'เมืองนครปฐม', 'บรรยากาศร่มรื่น ต้นไม้ใหญ่เยอะมาก พระตำหนักสวยงามคลาสสิก อากาศดีมาก', 'positive', 'บรรยากาศและความสวยงาม'),
('พุทธมณฑล', 'พุทธมณฑล', 'สถานที่กว้างขวาง ร่มรื่น เงียบสงบ เหมาะแก่การมาปฏิบัติธรรมและพักผ่อนหย่อนใจ', 'positive', 'บรรยากาศและความสวยงาม'),
('เซ็นทรัล ศาลายา', 'สามพราน', 'ห้างใหญ่ แอร์เย็นสบาย ร้านอาหารและร้านค้าครบครัน มีที่จอดรถสะดวกสบาย', 'positive', 'ที่จอดรถและการเดินทาง'),
('ตลาดโต้รุ่ง องค์พระปฐมเจดีย์', 'เมืองนครปฐม', 'สวรรค์ของคนชอบกิน หอยทอด บัวลอย ไอติมลอยฟ้า อร่อยระดับตำนาน แต่หาที่จอดยาก', 'neutral', 'ที่จอดรถและการเดินทาง');
